{
  "name": "opencode-smart-compaction",
  "version": "0.4.0",
  "description": "Smart Compaction for OpenCode 2: structured six-section checkpoints with protected identifiers and exact file and worktree state.",
  "license": "MIT",
  "author": "Shariq Riaz",
  "type": "module",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "compaction",
    "context",
    "summary"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/shariqriazz/opencode-smart-compaction.git"
  },
  "homepage": "https://github.com/shariqriazz/opencode-smart-compaction#readme",
  "bugs": {
    "url": "https://github.com/shariqriazz/opencode-smart-compaction/issues"
  },
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=22.19.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "check": "tsc --noEmit -p tsconfig.json",
    "test": "node --test test/*.test.ts",
    "validate": "bun run check && bun run test",
    "pack:inspect": "npm pack --dry-run --ignore-scripts"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.26"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.1.3",
    "@types/node": "^26.6.4",
    "typescript": "^7.0.2"
  }
}
